package eval

import (
	"strings"

	"github.com/prince/argus/internal/corpus"
)

// Grading is deliberately mechanical.
//
// Every question generated by the corpus package carries its own criteria, read
// off the ground-truth world rather than annotated by hand, so grading needs no
// LLM judge on the objective levels. That matters for three reasons: an
// LLM judge introduces variance the benchmark would then be measuring, it costs
// a model call per item per arm, and it is the single easiest place for a
// benchmark author to put their thumb on the scale.
//
// The cost is that grading is strict about surface form. An answer that is
// correct but never names the expected entity scores zero. That strictness
// applies identically to every arm, so it cannot favour one - and the required
// fragments are entity names and numbers, which any correct answer states.

// Outcome is how one arm did on one question.
type Outcome struct {
	QuestionID string       `json:"questionId"`
	Level      corpus.Level `json:"level"`
	Arm        string       `json:"arm"`

	Correct   bool `json:"correct"`
	Abstained bool `json:"abstained"`
	// ShouldAbstain mirrors the question, so the confusion matrix can be built
	// from outcomes alone.
	ShouldAbstain bool `json:"shouldAbstain"`
	// Poisoned is true when the answer repeated an assertion it should not have.
	Poisoned bool `json:"poisoned"`
	// Attributable is the share of the answer's claims that appear on the
	// returned derivation. Meaningless - and reported as absent - for an arm
	// with no derivation.
	Attributable  float64 `json:"attributable"`
	HasDerivation bool    `json:"hasDerivation"`

	GraphMS int64  `json:"graphMs"`
	TotalMS int64  `json:"totalMs"`
	Answer  string `json:"answer"`
	Err     string `json:"error,omitempty"`
}

// abstentionMarkers are the phrases that count as declining to answer.
//
// The baselines are told they may say "Insufficient evidence", so the primary
// marker is the one they were given. The rest catch a model that declines in
// its own words - which must count, or the comparison would credit ARGUS for
// phrasing rather than behaviour.
var abstentionMarkers = []string{
	"insufficient evidence",
	"not enough information",
	"do not contain enough",
	"does not contain enough",
	"cannot be determined",
	"cannot determine",
	"no information",
	"unable to answer",
	"not stated in",
	"not specified in",
	"the passages do not",
	"the context does not",
}

// DetectAbstention reports whether an answer declines to answer.
//
// It is applied uniformly: an arm that sets Response.Abstained explicitly is
// believed, and every other arm is judged on its text by the same rules.
func DetectAbstention(text string) bool {
	lower := strings.ToLower(text)
	for _, m := range abstentionMarkers {
		if strings.Contains(lower, m) {
			return true
		}
	}
	return false
}

// Grade scores one response against one question.
func Grade(q corpus.Question, arm string, r Response, err error) Outcome {
	out := Outcome{
		QuestionID:    q.ID,
		Level:         q.Level,
		Arm:           arm,
		ShouldAbstain: q.MustAbstain,
		GraphMS:       r.GraphMS,
		TotalMS:       r.TotalMS,
		Answer:        r.Text,
		HasDerivation: len(r.Claims) > 0,
	}
	if err != nil {
		out.Err = err.Error()
		return out
	}

	out.Abstained = r.Abstained || DetectAbstention(r.Text)
	lower := strings.ToLower(r.Text)

	// A forbidden fragment is a failure regardless of anything else. On L7 this
	// is the whole measurement: repeating the poisoned assertion is wrong even
	// if the surrounding answer is impeccable.
	for _, bad := range q.MustNotContain {
		if strings.Contains(lower, strings.ToLower(bad)) {
			out.Poisoned = true
		}
	}

	switch {
	case q.MustAbstain:
		// Correct means declining and not repeating the poison.
		out.Correct = out.Abstained && !out.Poisoned
	default:
		if out.Abstained || out.Poisoned {
			out.Correct = false
			break
		}
		out.Correct = true
		for _, want := range q.MustContain {
			if !strings.Contains(lower, strings.ToLower(want)) {
				out.Correct = false
				break
			}
		}
	}

	out.Attributable = attributable(r)
	return out
}

// attributable measures how much of the answer is backed by the derivation.
//
// The metric only means anything for an arm that returns a chain. A
// passage-based arm has no derivation to check against, so it reports zero with
// HasDerivation false - which is the honest result, not a penalty: the property
// is undefined for those systems, and the report says so rather than scoring
// them badly on it.
func attributable(r Response) float64 {
	if len(r.Claims) == 0 || strings.TrimSpace(r.Text) == "" {
		return 0
	}
	// Sentence-level check: each sentence of the answer should have some
	// overlap with a claim on the chain. This is a proxy - a strict entailment
	// check would need a model - but it catches the failure that matters, which
	// is prose asserting things the chain never contained.
	sentences := splitSentences(r.Text)
	if len(sentences) == 0 {
		return 0
	}
	grounded := 0
	for _, s := range sentences {
		for _, c := range r.Claims {
			if overlaps(s, c) {
				grounded++
				break
			}
		}
	}
	return float64(grounded) / float64(len(sentences))
}

// overlaps reports whether a sentence shares enough distinctive content with a
// claim to be considered grounded in it.
func overlaps(sentence, claim string) bool {
	st := contentWords(sentence)
	if len(st) == 0 {
		return true // nothing asserted, nothing to ground
	}
	ct := map[string]bool{}
	for _, w := range contentWords(claim) {
		ct[w] = true
	}
	hits := 0
	for _, w := range st {
		if ct[w] {
			hits++
		}
	}
	return float64(hits)/float64(len(st)) >= 0.4
}

var stopwords = map[string]bool{
	"the": true, "a": true, "an": true, "of": true, "in": true, "on": true,
	"and": true, "or": true, "to": true, "is": true, "was": true, "are": true,
	"were": true, "be": true, "by": true, "for": true, "as": true, "at": true,
	"that": true, "this": true, "it": true, "its": true, "with": true,
	"from": true, "has": true, "have": true, "had": true, "which": true,
}

func contentWords(s string) []string {
	var out []string
	for _, f := range strings.Fields(strings.ToLower(s)) {
		w := strings.Trim(f, ".,;:!?()[]\"'%")
		if w == "" || stopwords[w] || len(w) < 3 {
			continue
		}
		out = append(out, w)
	}
	return out
}

func splitSentences(s string) []string {
	var out []string
	cur := strings.Builder{}
	for _, r := range s {
		cur.WriteRune(r)
		if r == '.' || r == '!' || r == '?' || r == '\n' {
			if t := strings.TrimSpace(cur.String()); len(t) > 12 {
				out = append(out, t)
			}
			cur.Reset()
		}
	}
	if t := strings.TrimSpace(cur.String()); len(t) > 12 {
		out = append(out, t)
	}
	return out
}
